// Generated by Cypress Author on 2026-10-19 (SUI 04–08) e 2026-10-22 (SUI 03, SUI 07)
//
// SUI 04 · SUI 05 · SUI 06 · SUI 08 (P0) · SUI 03 · SUI 07 (P1) — Plano_de_Testes_QA_MatchWallet.md §9.1.
// O cálculo de pontuação/perfil é do backend (o front só envia respostas e exibe o retorno):
// aqui validamos o contrato enviado, a renderização de cada perfil e os estados do resultado.
// A classificação em si é verificada contra o servidor real em e2e/real/suitability-servidor.cy.ts.

import type { PerfilInvestidor } from '../../../src/services/types'

const PERGUNTAS = Array.from({ length: 5 }, (_, i) => ({
  id: `pergunta-${i + 1}`,
  enunciado: `Pergunta de teste ${i + 1}`,
  opcoes: [1, 2, 3].map((n) => ({ id: `p${i + 1}-o${n}`, texto: `Opção ${n}`, peso: n })),
}))

const CARTEIRA = {
  id: 'cart-1',
  nome: 'Carteira Moderada',
  perfilAlvo: 'MODERADO',
  descricao: null,
}

function resultado(pontuacao: number, perfil: PerfilInvestidor, comCarteira = true) {
  return {
    id: 'aval-1',
    usuarioId: '11111111-1111-4111-8111-111111111111',
    pontuacaoTotal: pontuacao,
    perfilResultante: perfil,
    carteiraRecomendada: comCarteira ? CARTEIRA : null,
    dataAvaliacao: '2026-10-07T12:00:00.000Z',
  }
}

/** Responde a pergunta `n` (1-based) clicando na opção indicada e confere o contador antes. */
function responder(n: number, opcao = 1) {
  cy.contains(`Pergunta ${n} de 5`).should('be.visible')
  cy.get('[data-cy="avaliacao-opcao"]')
    .eq(opcao - 1)
    .click()
}

describe('Plano QA · Avaliação de perfil (P0)', () => {
  beforeEach(() => {
    cy.bloquearApi()
    cy.stubSessao('cliente')
    cy.stubApi('GET', '/suitability/perguntas', PERGUNTAS, 'perguntas')
  })

  it('SUI 06 · responde as 5 perguntas → envia 1 resposta por pergunta com o usuarioId da sessão e mostra o resultado', () => {
    cy.stubApi('POST', '/suitability/avaliar', resultado(25, 'MODERADO'), 'avaliar')
    cy.visit('/avaliacao-perfil')

    // Estado inicial (SUI 01/02): primeira pergunta, 3 opções, Voltar desabilitado.
    cy.contains('Pergunta 1 de 5').should('be.visible')
    cy.get('[data-cy="avaliacao-opcao"]').should('have.length', 3)
    cy.get('[data-cy="avaliacao-voltar"]').should('be.disabled')

    for (let n = 1; n <= 5; n++) {
      responder(n, 2)
    }

    cy.wait('@avaliar')
      .its('request.body')
      .should('deep.equal', {
        respostas: PERGUNTAS.map((p) => ({
          perguntaId: p.id,
          opcaoId: `${p.id.replace('pergunta-', 'p')}-o2`,
        })),
        usuarioId: '11111111-1111-4111-8111-111111111111',
      })

    cy.get('[data-cy="avaliacao-perfil-resultado"]')
      .invoke('text')
      .should('match', /moderado/i)
    cy.get('[data-cy="avaliacao-pontuacao"]').should('contain.text', 'Pontuação 25')
    // A sessão é recarregada para refletir perfil/carteira novos.
    cy.get('@me.all').should('have.length.at.least', 2)
  })

  it('SUI 02/03 · usa a tecla 2 e depois Voltar → avança uma única pergunta e retorna à anterior', () => {
    cy.visit('/avaliacao-perfil')

    cy.contains('Pergunta 1 de 5').should('be.visible')
    cy.get('[data-cy="avaliacao-opcoes"]').trigger('keydown', { key: '2' })

    cy.contains('Pergunta 2 de 5').should('be.visible')
    cy.get('[data-cy="avaliacao-voltar"]').should('be.enabled').click()
    cy.contains('Pergunta 1 de 5').should('be.visible')

    // Tecla fora do intervalo 1–3 não responde nada.
    cy.get('[data-cy="avaliacao-opcoes"]').trigger('keydown', { key: '9' })
    cy.contains('Pergunta 1 de 5').should('be.visible')
  })

  it('SUI 08 · perfil sem carteira ativa → avisa a ausência, não inventa recomendação e permite refazer', () => {
    cy.stubApi('POST', '/suitability/avaliar', resultado(55, 'SOFISTICADO', false), 'avaliar')
    cy.visit('/avaliacao-perfil')

    for (let n = 1; n <= 5; n++) {
      responder(n, 3)
    }
    cy.wait('@avaliar')

    cy.get('[data-cy="avaliacao-sem-carteira"]')
      .should('be.visible')
      .and('contain.text', 'Ainda não há uma carteira recomendada')
    cy.contains('A carteira abaixo é a recomendada').should('not.exist')

    cy.get('[data-cy="avaliacao-refazer"]').click()
    cy.contains('Pergunta 1 de 5').should('be.visible')
    cy.get('[data-cy="avaliacao-resultado"]').should('not.exist')
  })

  // SUI 05: a tabela do plano. O stub devolve o perfil esperado para cada pontuação-limite e
  // garantimos que a UI mostra exatamente o que o servidor classificou (sem recalcular).
  const FRONTEIRAS: Array<[number, PerfilInvestidor]> = [
    [0, 'CONSERVADOR'],
    [17, 'CONSERVADOR'],
    [18, 'MODERADO'],
    [32, 'MODERADO'],
    [33, 'ARROJADO'],
    [46, 'ARROJADO'],
    [47, 'SOFISTICADO'],
    [60, 'SOFISTICADO'],
  ]

  for (const [pontuacao, perfil] of FRONTEIRAS) {
    it(`SUI 05 · pontuação ${pontuacao} classificada como ${perfil} → resultado exibe o perfil e a pontuação devolvidos`, () => {
      cy.stubApi('POST', '/suitability/avaliar', resultado(pontuacao, perfil), 'avaliar')
      cy.visit('/avaliacao-perfil')

      for (let n = 1; n <= 5; n++) {
        responder(n)
      }
      cy.wait('@avaliar')

      cy.get('[data-cy="avaliacao-perfil-resultado"]')
        .invoke('text')
        .should('match', new RegExp(perfil, 'i'))
      cy.get('[data-cy="avaliacao-pontuacao"]').should('contain.text', `Pontuação ${pontuacao} `)
    })
  }
})

describe('Plano QA · Avaliação de perfil · atalhos de teclado (SUI 03)', () => {
  beforeEach(() => {
    cy.bloquearApi()
    cy.stubSessao('cliente')
    cy.stubApi('GET', '/suitability/perguntas', PERGUNTAS, 'perguntas')
    cy.stubApi('POST', '/suitability/avaliar', resultado(25, 'MODERADO'), 'avaliar')
  })

  // Os atalhos escutam `keydown` na janela; o evento é disparado no <fieldset> e sobe até lá. O radio é
  // `sr-only` e o Cypress sempre o considera coberto, então não se dispara nele.
  for (const tecla of [1, 2, 3]) {
    it(`SUI 03 · tecla ${tecla} na primeira pergunta → escolhe a opção ${tecla}, avança uma só pergunta e envia essa opção`, () => {
      cy.visit('/avaliacao-perfil')
      cy.contains('Pergunta 1 de 5').should('be.visible')

      cy.get('[data-cy="avaliacao-opcoes"]').trigger('keydown', { key: String(tecla) })
      cy.contains('Pergunta 2 de 5').should('be.visible')

      for (let n = 2; n <= 5; n++) responder(n, 1)
      cy.wait('@avaliar')
        .its('request.body.respostas.0')
        .should('deep.equal', { perguntaId: 'pergunta-1', opcaoId: `p1-o${tecla}` })
    })
  }

  it('SUI 03 · teclas inválidas e atalhos anunciados → nenhuma responde; cada número coincide com a opção exibida', () => {
    cy.visit('/avaliacao-perfil')
    cy.contains('Pergunta 1 de 5').should('be.visible')

    // 0, 4 (acima de 3 opções), letra, espaço e Enter não respondem nada.
    for (const key of ['0', '4', 'a', ' ', 'Enter', '-']) {
      cy.get('[data-cy="avaliacao-opcoes"]').trigger('keydown', { key })
    }
    cy.contains('Pergunta 1 de 5').should('be.visible')
    cy.get('[data-cy="avaliacao-opcao"] input:checked').should('not.exist')

    // Número do selo, `aria-keyshortcuts` e posição da opção são o mesmo; todas focáveis por Tab.
    cy.get('[data-cy="avaliacao-opcao"]').each(($opcao, indice) => {
      const numero = String(indice + 1)
      cy.wrap($opcao).find('input').should('have.attr', 'aria-keyshortcuts', numero)
      cy.wrap($opcao).find('[aria-hidden="true"]').should('have.text', numero)
      cy.wrap($opcao).find('input').focus().should('have.focus')
    })
    cy.get('[data-cy="avaliacao-opcao"] input').each(($radio) => {
      expect($radio.attr('tabindex'), 'tabindex').not.to.eq('-1')
    })
    // As três opções formam um único grupo de rádio dentro de um fieldset rotulado pela pergunta.
    cy.get('fieldset[data-cy="avaliacao-opcoes"]')
      .should('have.attr', 'aria-labelledby')
      .and('not.be.empty')
    cy.get('[data-cy="avaliacao-opcao"] input[name="avaliacao-perfil-opcao"]').should(
      'have.length',
      3,
    )
  })

  // Segurar a tecla 2 dispara repetições; `event.repeat` é ignorado para não saltar o questionário.
  it('SUI 03 · tecla repetida (segurada) → não responde as perguntas seguintes', () => {
    cy.visit('/avaliacao-perfil')
    cy.get('[data-cy="avaliacao-opcoes"]').trigger('keydown', { key: '2' })
    cy.contains('Pergunta 2 de 5').should('be.visible')

    cy.get('[data-cy="avaliacao-opcoes"]').trigger('keydown', { key: '2', repeat: true })
    cy.contains('Pergunta 2 de 5').should('be.visible')
    cy.get('@avaliar.all').should('have.length', 0)
  })

  // A dica da tela promete "use as teclas 1 a 3 para responder": o atalho vale sem foco prévio.
  it('SUI 03 · tecla 2 logo ao abrir, sem focar nada → responde', () => {
    cy.visit('/avaliacao-perfil')
    cy.contains('Pergunta 1 de 5').should('be.visible')
    cy.get('body').type('2')
    cy.contains('Pergunta 2 de 5').should('be.visible')
  })
})

describe('Plano QA · Avaliação de perfil · interrupção e reenvio (SUI 07)', () => {
  beforeEach(() => {
    cy.bloquearApi()
    cy.stubSessao('cliente')
    cy.stubApi('GET', '/suitability/perguntas', PERGUNTAS, 'perguntas')
  })

  it('SUI 07 · sai, volta e recarrega no meio do questionário → recomeça na pergunta 1 e nada é enviado como concluído', () => {
    cy.stubApi('POST', '/suitability/avaliar', resultado(25, 'MODERADO'), 'avaliar')
    cy.visit('/avaliacao-perfil')
    responder(1, 2)
    responder(2, 2)
    cy.contains('Pergunta 3 de 5').should('be.visible')

    // Recarregar: o progresso não é guardado, a jornada recomeça.
    cy.reload()
    cy.contains('Pergunta 1 de 5').should('be.visible')
    cy.get('[data-cy="avaliacao-opcao"] input:checked').should('not.exist')
    cy.get('[data-cy="avaliacao-voltar"]').should('be.disabled')

    // Sair para o painel e voltar: idem.
    responder(1, 1)
    cy.contains('Pergunta 2 de 5').should('be.visible')
    cy.visit('/conta')
    cy.visit('/avaliacao-perfil')
    cy.contains('Pergunta 1 de 5').should('be.visible')

    // Nenhuma avaliação parcial foi tratada como concluída.
    cy.get('@avaliar.all').should('have.length', 0)
    cy.get('[data-cy="avaliacao-resultado"]').should('not.exist')
  })

  it('SUI 07 · conclusão falha por timeout e é refeita → erro sem resultado, sem recarregar a sessão e uma só avaliação ao final', () => {
    let chamadas = 0
    cy.intercept('POST', '**/api/v1/suitability/avaliar', (req) => {
      chamadas += 1
      if (chamadas === 1) {
        req.reply({
          statusCode: 504,
          body: {
            error: { code: 'GATEWAY_TIMEOUT', message: 'O servidor demorou para responder.' },
          },
        })
        return
      }
      req.reply({ statusCode: 201, body: resultado(25, 'MODERADO'), delay: 400 })
    }).as('avaliar')

    cy.visit('/avaliacao-perfil')
    for (let n = 1; n <= 5; n++) responder(n, 2)
    cy.wait('@avaliar')

    // Falha: mensagem, nenhuma tela de resultado e a sessão não foi tocada.
    cy.get('[role="alert"]').should('contain.text', 'Não foi possível concluir a avaliação.')
    cy.get('[data-cy="avaliacao-perfil-resultado"]').should('not.exist')
    cy.get('[data-cy="avaliacao-pontuacao"]').should('not.exist')
    cy.get('@me.all').should('have.length', 1)

    // Refazer: recarrega e responde de novo; clique duplo na última opção envia uma vez só.
    cy.reload()
    for (let n = 1; n <= 4; n++) responder(n, 2)
    cy.contains('Pergunta 5 de 5').should('be.visible')
    cy.get('[data-cy="avaliacao-opcao"]').eq(1).dblclick()
    cy.get('[data-cy="avaliacao-pontuacao"]').should('contain.text', 'Pontuação 25')
    cy.get('@avaliar.all').should('have.length', 2)
    cy.get('[data-cy="avaliacao-perfil-resultado"]').should('have.length', 1)
  })

  // ATENÇÃO — deve FALHAR: depois do erro de conclusão a tela só mostra o alerta, sem botão nem
  // link; as respostas já dadas se perdem e o cliente só sai recarregando a página.
  it('SUI 07 · falha na conclusão → a tela oferece como tentar de novo (falha até existir "Tentar novamente")', () => {
    cy.stubErroApi(
      'POST',
      '/suitability/avaliar',
      { status: 504, code: 'GATEWAY_TIMEOUT', message: 'O servidor demorou para responder.' },
      'avaliar',
    )
    cy.visit('/avaliacao-perfil')
    for (let n = 1; n <= 5; n++) responder(n, 2)
    cy.wait('@avaliar')
    cy.get('[role="alert"]').should('be.visible')

    cy.get('main button, main a').filter(':visible').should('have.length.at.least', 1)
  })
})
